// ─── Time entries: a week of driver duty hours matching the overtime cases in docs/KONSEP_LEMBUR_SUPIR.md ──
const byHandle = (handle) => employees.find((e) => e.email.startsWith(`${handle}@`))
const entry = (handle, startDate, startTime, endDate, endTime) => {
  const e = byHandle(handle)
  return { employeeNumber: e.nik, employeeId: e.id, employeeName: e.name, startDate, startTime, endDate, endTime,
    batchId: 'seed', batchLabel: 'Contoh data awal (jam tugas supir)', importedAt: '2026-11-26T01:00:00.000Z' }
}
