// ─── Recruitment: open driver seats ──────────────────────────────────────
const REQ = (o) => ({
  employmentType: 'Contract', headcount: 1, priority: 'Medium', targetDate: '', publishStartDate: '', publishEndDate: '',
  notes: '', publicTitle: '', jobDescription: '', ...o,
})
const vacantSeat = (positionId, nth = 1) => headcounts.filter((h) => h.positionId === positionId && !h.employeeId)[nth - 1]
const posId = (name, deptId) => structure.positions.find((p) => p.name === name && p.departmentId === deptId)?.id
const JKT_LH = 8, JKT_DD = 9, SBY_LH = 13   // department ids of Driver Linehaul / Distribusi (see structure.json)
const head = (handle) => byHandle(handle)

